insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (114, 8, 1, 19, 'سورة الأنفال ١ – ١٩', '«يسألونك عن الأنفال»، «إنما المؤمنون»، وإمداد الله يوم بدر: «وما رميت إذ رميت»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 114) = $j$[{"lbl": "الآيات ١ – ٤", "q": "يَسۡـَٔلُونَكَ عَنِ ٱلۡأَنفَالِۖ قُلِ ٱلۡأَنفَالُ لِلَّهِ وَٱلرَّسُولِۖ فَٱتَّقُواْ ٱللَّهَ وَأَصۡلِحُواْ ذَاتَ بَيۡنِكُمۡۖ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤۡمِنِينَ ﴿١﴾ إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٢﴾ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿٣﴾ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٤﴾", "w": [["الأنفال", "جمع نفَل: ما يعطيه الإمام لأفراد الجيش زيادة على سهمهم من الغنيمة."], ["ذات بينكم", "حقيقة بينكم، والبين: الوصلة والرابطة التي تربط بعضكم ببعض من المودة والإخاء."], ["إنما المؤمنون", "الكاملون في إيمانهم."], ["وجلت قلوبهم", "خافت، والوجل: الخوف، لا سيما عند ذكر وعيده."], ["وعلى ربهم يتوكلون", "على الله وحده يعتمدون، وإليه أمرهم يفوّضون."], ["ومما رزقناهم", "أي أعطيناهم."], ["أولئك", "الموصوفون بالصفات الخمس السابقة."], ["ورزق كريم", "عطاء عظيم من سائر وجوه النعيم في الجنة."]], "m": "نزلت في غزوة بدر، وكان النبي ﷺ قد نفّل بعض المجاهدين لبلائهم، فحصلت تساؤلات: لم يُعطى هذا ولا يُعطى ذاك؟ فسألوا الرسول ﷺ، فأنزل الله: يسألونك عن الأنفال، قل الأنفال لله والرسول، فالله يحكم فيها بما يشاء، والرسول يقسمها كما يأمره ربه، فاتقوا الله بترك النزاع، وأصلحوا ذات بينكم بتوثيق عرى المحبة، وتصفية قلوبكم من كل ضغن نشأ من الأنفال، وأطيعوا الله ورسوله إن كنتم مؤمنين حقاً. إنما المؤمنون الكاملون الذين إذا ذُكر الله، اسمه أو وعده أو وعيده، وجلت قلوبهم فأقلعت عن المعصية وأسرعت إلى الطاعة، وإذا تُليت عليهم آياته زادتهم إيماناً ويقيناً، وعلى ربهم لا على غيره يتوكّلون، الذين يقيمون الصلاة بكامل شروطها وأركانها وسننها وآدابها، ومما رزقناهم من مال وعلم وجاه وصحة ينفقون في سبيل الله، أولئك هم المؤمنون حقاً، لهم درجات عند ربهم، منازل عالية في الجنة، ومغفرة كاملة لذنوبهم، ورزق كريم طيب واسع.", "h": ["الأمر بتقوى الله عز وجل، وإصلاح ذات البين.", "الإيمان يزيد بالطاعة، وينقص بالعصيان.", "من المؤمنين من هو كامل الإيمان، ومنهم من هو ناقصه.", "من صفات أهل الإيمان الكامل ما ورد في الآية الثانية من هذه السورة وما بعدها."], "k": "«إنما المؤمنون الذين إذا ذُكر الله وجلت قلوبهم»… متى آخر مرة اهتزّ قلبي عند ذكر الله؟"}, {"lbl": "الآيات ٥ – ٨", "q": "كَمَآ أَخۡرَجَكَ رَبُّكَ مِنۢ بَيۡتِكَ بِٱلۡحَقِّ وَإِنَّ فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ لَكَٰرِهُونَ ﴿٥﴾ يُجَٰدِلُونَكَ فِي ٱلۡحَقِّ بَعۡدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلۡمَوۡتِ وَهُمۡ يَنظُرُونَ ﴿٦﴾ وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ ﴿٧﴾ لِيُحِقَّ ٱلۡحَقَّ وَيُبۡطِلَ ٱلۡبَٰطِلَ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ ﴿٨﴾", "w": [["من بيتك", "أي المدينة المنورة."], ["إحدى الطائفتين", "العير «القافلة» أو النفير: نفير قريش وجيشها."], ["يُبطل الباطل", "يُذهبه بإذلال أهله وكسر شوكتهم وهزيمتهم."], ["ولو كره المجرمون", "كفار قريش المشركون."]], "m": "كما أخرجك ربك أيها الرسول من بيتك بالمدينة بالحق، بإذن الله، وإن فريقاً من المؤمنين لكارهون لما علموا بخروج قريش لقتالهم، وكانت العاقبة خيراً عظيماً، فهذه الحال مثل حالهم لما كرهوا نزع الغنائم من أيديهم وتولّيك قسمتها، تشبيه حال حاضرة بحال ماضية، كرهها بعض المؤمنين وكانت العاقبة خيراً. يجادلونك في القتال بعدما تبيّن أن العير نجت ولم يبق إلا النفير، كأنما يُساقون إلى الموت وهم ينظرون، من شدة كراهيتهم لقتال لم يستعدّوا له. واذكر إذ يعدكم الله إحدى الطائفتين أنها لكم، وتودّون أن غير ذات الشوكة، عير أبي سفيان، تكون لكم، لأنها مغنم بلا مغرم لقلة عددها وعدّتها، ويريد الله أن يحقّ الحق بكلماته التي أمركم فيها بقتال الكافرين وأمر الملائكة بالقتال معكم، ويقطع دابر الكافرين، ليحقّ الحق وهو الإسلام، ويبطل الباطل وهو الشرك، ولو كره المجرمون.", "h": ["تقرير قاعدة «عسى أن تكرهوا شيئاً وهو خير لكم»: فقد بلغ النبي ﷺ أن عيراً لقريش قادمة من الشام يقودها أبو سفيان، فانتدب بعض أصحابه للخروج إليها، لأن قريشاً صادرت أموال بعضهم، وأخبرهم أن الله وعدهم إحدى الطائفتين، فلما نجت العير وقدم النفير استشارهم، فوافقوا على القتال ببدر وكره بعضهم ذلك، فأنزل الله هذه الآيات.", "بيان ضعف الإنسان في رغبته في كل ما لا كلفة فيه ولا مشقة.", "إنجاز الله تعالى وعده للمؤمنين، إذ أغنمهم طائفة النفير وأعزّهم بنصر لم يكونوا يتوقّعونه.", "ذكر نبذة عن وقعة بدر، وهي من أشهر الوقائع وأفضلها، وأهلها من أفضل الصحابة وخيارهم، إذ كانت في حال ضعف المسلمين في السنة الثانية من الهجرة، وهم أقلية والعرب كلهم أعداء لهم."], "k": "«وتودّون أن غير ذات الشوكة تكون لكم»… كم مرة كرهت أمراً شاقاً فكان فيه خيري؟"}, {"lbl": "الآيات ٩ – ١٤", "q": "إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُرۡدِفِينَ ﴿٩﴾ وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ ﴿١٠﴾ إِذۡ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةٗ مِّنۡهُ وَيُنَزِّلُ عَلَيۡكُم مِّنَ ٱلسَّمَآءِ مَآءٗ لِّيُطَهِّرَكُم بِهِۦ وَيُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّيۡطَٰنِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ ﴿١١﴾ إِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَـٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ سَأُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ فَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ ﴿١٢﴾ ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿١٣﴾ ذَٰلِكُمۡ فَذُوقُوهُ وَأَنَّ لِلۡكَٰفِرِينَ عَذَابَ ٱلنَّارِ ﴿١٤﴾", "w": [["تستغيثون", "تطلبون الغوث من الله تعالى، وهو النصر على عدوكم."], ["مُردفين", "متتابعين، بعضهم ردف بعض، أي متلاحقين."], ["وما جعله الله إلا بشرى", "ما جعل الإمداد بالملائكة إلا بشرى لكم بالنصر."], ["إذ يغشّيكم النعاس", "يغطّيكم به، والنعاس: نوم خفيف جداً."], ["أمنة", "أمناً من الخوف الذي أصابكم لقلّتكم وكثرة عدوكم."], ["رجز الشيطان", "وسواسه لكم بما يؤلمكم ويحزنكم."], ["وليربط على قلوبكم", "يشدّ عليها بالصبر واليقين."], ["ويثبّت به الأقدام", "بالمطر، حتى لا تسوخ في الرمال."], ["الرعب", "الخوف والفزع."], ["فاضربوا منهم كل بنان", "أطراف اليدين والرجلين حتى يعوقهم عن الضرب والفرار."], ["شاقّوا الله ورسوله", "خالفوه في مراده منهم فلم يطيعوه، وخالفوا رسوله."], ["ذلكم فذوقوه", "أي العذاب فذوقوه."], ["عذاب النار", "أي في الآخرة."]], "m": "ما زال السياق في غزوة بدر ونعمها: اذكروا إذ كنتم خائفين لقلّتكم وكثرة عدوكم فاستغثتم ربكم: اللهم نصرك، اللهم أنجز لي ما وعدتني، فاستجاب لكم: أني ممدّكم بألف من الملائكة مردفين متتابعين، وما جعله الله إلا بشرى لكم ولتطمئن به قلوبكم، أما النصر فمن عند الله، إن الله عزيز حكيم. ونعمة ثانية: إذ يغشّيكم النعاس أمنة منه، فإن العبد إذا خامره النعاس هدأ وسكن وذهب عنه الخوف فثبت. ونعمة أخرى: كانت الأرض رملية تسوخ فيها أقدامهم، وقلّ ماؤهم فصاروا عطاشاً محدثين، ووسوس الشيطان لبعضهم: تقاتلون محدثين عطاشاً وعدوكم ريّان، فأنزل الله على معسكرهم خاصة مطراً غزيراً شربوا منه وتطهّروا، وتلبّدت به التربة، وذهب رجز الشيطان، وربط على قلوبهم بالصبر واليقين، وثبّت به الأقدام. ونعمة أخرى: إذ يوحي ربك إلى الملائكة: أني معكم فثبّتوا الذين آمنوا بالكلام المشجّع، سألقي في قلوب الذين كفروا الرعب، فاضربوا فوق الأعناق، واضربوا منهم كل بنان. ذلك بأنهم عادوا الله ورسوله، ومن يشاقق الله ورسوله فإن الله شديد العقاب، ذلكم القتل والهزيمة فذوقوه في الدنيا، وأن للكافرين في الآخرة عذاب النار.", "h": ["مشروعية الاستغاثة بالله تعالى، وهي عبادة، فلا يصح أن يُستغاث بغير الله تعالى.", "تقرير عقيدة أن الملائكة عباد لله يسخّرهم في فعل ما يشاء، وقد سخّرهم للقتال مع المؤمنين فقاتلوا ونصروا وثبّتوا، وذلك بأمر الله تعالى لهم.", "تعداد نعم الله تعالى على المؤمنين في غزوة بدر، وهي كثيرة.", "مشاقّة الله ورسوله كفر يستوجب صاحبها عذاب الدنيا وعذاب الآخرة.", "تعليم الله تعالى عباده كيف يقاتلون ويضربون أعداءهم، وهذا شرف كبير للمؤمنين."], "k": "«إذ تستغيثون ربكم فاستجاب لكم»… في ضيقي، إلى من أستغيث أولاً؟"}, {"lbl": "الآيات ١٥ – ١٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ زَحۡفٗا فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ ﴿١٥﴾ وَمَن يُوَلِّهِمۡ يَوۡمَئِذٖ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفٗا لِّقِتَالٍ أَوۡ مُتَحَيِّزًا إِلَىٰ فِئَةٖ فَقَدۡ بَآءَ بِغَضَبٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿١٦﴾ فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿١٧﴾ ذَٰلِكُمۡ وَأَنَّ ٱللَّهَ مُوهِنُ كَيۡدِ ٱلۡكَٰفِرِينَ ﴿١٨﴾ إِن تَسۡتَفۡتِحُواْ فَقَدۡ جَآءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُواْ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَعُودُواْ نَعُدۡ وَلَن تُغۡنِيَ عَنكُمۡ فِئَتُكُمۡ شَيۡـٔٗا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِينَ ﴿١٩﴾", "w": [["زحفاً", "زاحفين لكثرتهم وبطء سيرهم، كأنهم يزحفون على الأرض."], ["متحرّفاً لقتال", "مائلاً من جهة إلى أخرى ليتمكّن من ضرب العدو وقتاله."], ["أو متحيّزاً إلى فئة", "يريد الانحياز إلى جماعة من المؤمنين تقاتل."], ["فقد باء بغضب", "رجع من المعركة مصحوباً بغضب من الله لمعصيته."], ["وليُبلي المؤمنين", "لينعم عليهم بنعمة النصر والظفر على قلة عددهم."], ["فئتكم", "مقاتلتكم من رجالكم الكثيرين."]], "m": "ينادي الرب المؤمنين: إذا لقيتم الذين كفروا زاحفين إليكم فلا تولّوهم الأدبار، فلا تنهزموا أمامهم فتمكّنوهم من قتلكم، ومن يولّهم يومئذ دبره إلا متحرّفاً لقتال ليتمكّن من عدوه، أو متحيّزاً إلى فئة من المؤمنين تقاتل، فقد باء بغضب من الله، ومأواه جهنم وبئس المصير. فلم تقتلوهم ولكن الله قتلهم، فهو الذي أمركم وأقدركم وأعانكم، حتى لا يخطر ببالكم أنكم المقاتلون وحدكم، وما رميت إذ رميت ولكن الله رمى، فحثية التراب التي رماها الرسول ﷺ وصلت إلى جلّ أعين المشركين فأذهلتهم وعوّقتهم عن القتال، والله هو الذي أوصلها، وليُبلي المؤمنين منه بلاءً حسناً بنصرهم في الدنيا وإدخالهم الجنة في الآخرة، إن الله سميع لاستغاثتهم، عليم بضعفهم. ذلكم، وأن الله موهن كيد الكافرين، فكلما كادوا لأوليائه أضعفه وأبطله. وقال أبو جهل وغيره: اللهم أيّنا كان أقطع للرحم وأتانا بما لا نعرف فأحِنه الغداة، فقال الله: إن تستفتحوا، تطلبوا القضاء بينكم وبين محمد، فقد جاءكم الفتح بهزيمتكم في بدر، وإن تنتهوا عن الحرب وتُسلموا فهو خير لكم، وإن تعودوا نعد فنسلّط عليكم رسولنا والمؤمنين، ولن تغني عنكم فئتكم شيئاً ولو كثرت، وأن الله مع المؤمنين ما استقاموا على طاعته.", "h": ["حرمة الفرار من العدو الكافر عند اللقاء، لما توعّد الله عليه من الغضب والعذاب، ولعدّ الرسول ﷺ له من الموبقات السبع في حديث مسلم: «والتولّي يوم الزحف».", "تقرير مبدأ أن الله تعالى خالق كل شيء، وأنه خلق العبد وخلق فعله، إذ لما كان العبد مخلوقاً وقدرته مخلوقة، ولا يصدر منه فعل ولا قول إلا بإقدار الله له، كان الفاعل الحقيقي هو الله، وما للعبد إلا الكسب بجوارحه، وبذلك يُجزى الخير بالخير والشر بمثله.", "آية وصول حثية التراب من كف الرسول ﷺ إلى أغلب عيون المشركين في المعركة.", "إكرام الله تعالى وإبلاؤه لأوليائه البلاء الحسن، فله الحمد وله المنّة.", "ولاية الله للمؤمنين الصادقين هي أسباب نصرهم وكمالهم وإسعادهم."], "k": "«وما رميت إذ رميت ولكن الله رمى»… حين أنجح في أمر، هل أنسبه لنفسي أم لتوفيق ربي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 114;
insert into public.tdb_cards(topic, i, body) select 114, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "يَسۡـَٔلُونَكَ عَنِ ٱلۡأَنفَالِۖ قُلِ ٱلۡأَنفَالُ لِلَّهِ وَٱلرَّسُولِۖ فَٱتَّقُواْ ٱللَّهَ وَأَصۡلِحُواْ ذَاتَ بَيۡنِكُمۡۖ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤۡمِنِينَ ﴿١﴾ إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٢﴾ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿٣﴾ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٤﴾", "w": [["الأنفال", "جمع نفَل: ما يعطيه الإمام لأفراد الجيش زيادة على سهمهم من الغنيمة."], ["ذات بينكم", "حقيقة بينكم، والبين: الوصلة والرابطة التي تربط بعضكم ببعض من المودة والإخاء."], ["إنما المؤمنون", "الكاملون في إيمانهم."], ["وجلت قلوبهم", "خافت، والوجل: الخوف، لا سيما عند ذكر وعيده."], ["وعلى ربهم يتوكلون", "على الله وحده يعتمدون، وإليه أمرهم يفوّضون."], ["ومما رزقناهم", "أي أعطيناهم."], ["أولئك", "الموصوفون بالصفات الخمس السابقة."], ["ورزق كريم", "عطاء عظيم من سائر وجوه النعيم في الجنة."]], "m": "نزلت في غزوة بدر، وكان النبي ﷺ قد نفّل بعض المجاهدين لبلائهم، فحصلت تساؤلات: لم يُعطى هذا ولا يُعطى ذاك؟ فسألوا الرسول ﷺ، فأنزل الله: يسألونك عن الأنفال، قل الأنفال لله والرسول، فالله يحكم فيها بما يشاء، والرسول يقسمها كما يأمره ربه، فاتقوا الله بترك النزاع، وأصلحوا ذات بينكم بتوثيق عرى المحبة، وتصفية قلوبكم من كل ضغن نشأ من الأنفال، وأطيعوا الله ورسوله إن كنتم مؤمنين حقاً. إنما المؤمنون الكاملون الذين إذا ذُكر الله، اسمه أو وعده أو وعيده، وجلت قلوبهم فأقلعت عن المعصية وأسرعت إلى الطاعة، وإذا تُليت عليهم آياته زادتهم إيماناً ويقيناً، وعلى ربهم لا على غيره يتوكّلون، الذين يقيمون الصلاة بكامل شروطها وأركانها وسننها وآدابها، ومما رزقناهم من مال وعلم وجاه وصحة ينفقون في سبيل الله، أولئك هم المؤمنون حقاً، لهم درجات عند ربهم، منازل عالية في الجنة، ومغفرة كاملة لذنوبهم، ورزق كريم طيب واسع.", "h": ["الأمر بتقوى الله عز وجل، وإصلاح ذات البين.", "الإيمان يزيد بالطاعة، وينقص بالعصيان.", "من المؤمنين من هو كامل الإيمان، ومنهم من هو ناقصه.", "من صفات أهل الإيمان الكامل ما ورد في الآية الثانية من هذه السورة وما بعدها."], "k": "«إنما المؤمنون الذين إذا ذُكر الله وجلت قلوبهم»… متى آخر مرة اهتزّ قلبي عند ذكر الله؟"}, {"lbl": "الآيات ٥ – ٨", "q": "كَمَآ أَخۡرَجَكَ رَبُّكَ مِنۢ بَيۡتِكَ بِٱلۡحَقِّ وَإِنَّ فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ لَكَٰرِهُونَ ﴿٥﴾ يُجَٰدِلُونَكَ فِي ٱلۡحَقِّ بَعۡدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلۡمَوۡتِ وَهُمۡ يَنظُرُونَ ﴿٦﴾ وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ ﴿٧﴾ لِيُحِقَّ ٱلۡحَقَّ وَيُبۡطِلَ ٱلۡبَٰطِلَ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ ﴿٨﴾", "w": [["من بيتك", "أي المدينة المنورة."], ["إحدى الطائفتين", "العير «القافلة» أو النفير: نفير قريش وجيشها."], ["يُبطل الباطل", "يُذهبه بإذلال أهله وكسر شوكتهم وهزيمتهم."], ["ولو كره المجرمون", "كفار قريش المشركون."]], "m": "كما أخرجك ربك أيها الرسول من بيتك بالمدينة بالحق، بإذن الله، وإن فريقاً من المؤمنين لكارهون لما علموا بخروج قريش لقتالهم، وكانت العاقبة خيراً عظيماً، فهذه الحال مثل حالهم لما كرهوا نزع الغنائم من أيديهم وتولّيك قسمتها، تشبيه حال حاضرة بحال ماضية، كرهها بعض المؤمنين وكانت العاقبة خيراً. يجادلونك في القتال بعدما تبيّن أن العير نجت ولم يبق إلا النفير، كأنما يُساقون إلى الموت وهم ينظرون، من شدة كراهيتهم لقتال لم يستعدّوا له. واذكر إذ يعدكم الله إحدى الطائفتين أنها لكم، وتودّون أن غير ذات الشوكة، عير أبي سفيان، تكون لكم، لأنها مغنم بلا مغرم لقلة عددها وعدّتها، ويريد الله أن يحقّ الحق بكلماته التي أمركم فيها بقتال الكافرين وأمر الملائكة بالقتال معكم، ويقطع دابر الكافرين، ليحقّ الحق وهو الإسلام، ويبطل الباطل وهو الشرك، ولو كره المجرمون.", "h": ["تقرير قاعدة «عسى أن تكرهوا شيئاً وهو خير لكم»: فقد بلغ النبي ﷺ أن عيراً لقريش قادمة من الشام يقودها أبو سفيان، فانتدب بعض أصحابه للخروج إليها، لأن قريشاً صادرت أموال بعضهم، وأخبرهم أن الله وعدهم إحدى الطائفتين، فلما نجت العير وقدم النفير استشارهم، فوافقوا على القتال ببدر وكره بعضهم ذلك، فأنزل الله هذه الآيات.", "بيان ضعف الإنسان في رغبته في كل ما لا كلفة فيه ولا مشقة.", "إنجاز الله تعالى وعده للمؤمنين، إذ أغنمهم طائفة النفير وأعزّهم بنصر لم يكونوا يتوقّعونه.", "ذكر نبذة عن وقعة بدر، وهي من أشهر الوقائع وأفضلها، وأهلها من أفضل الصحابة وخيارهم، إذ كانت في حال ضعف المسلمين في السنة الثانية من الهجرة، وهم أقلية والعرب كلهم أعداء لهم."], "k": "«وتودّون أن غير ذات الشوكة تكون لكم»… كم مرة كرهت أمراً شاقاً فكان فيه خيري؟"}, {"lbl": "الآيات ٩ – ١٤", "q": "إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُرۡدِفِينَ ﴿٩﴾ وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ ﴿١٠﴾ إِذۡ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةٗ مِّنۡهُ وَيُنَزِّلُ عَلَيۡكُم مِّنَ ٱلسَّمَآءِ مَآءٗ لِّيُطَهِّرَكُم بِهِۦ وَيُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّيۡطَٰنِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ ﴿١١﴾ إِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَـٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ سَأُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ فَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ ﴿١٢﴾ ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿١٣﴾ ذَٰلِكُمۡ فَذُوقُوهُ وَأَنَّ لِلۡكَٰفِرِينَ عَذَابَ ٱلنَّارِ ﴿١٤﴾", "w": [["تستغيثون", "تطلبون الغوث من الله تعالى، وهو النصر على عدوكم."], ["مُردفين", "متتابعين، بعضهم ردف بعض، أي متلاحقين."], ["وما جعله الله إلا بشرى", "ما جعل الإمداد بالملائكة إلا بشرى لكم بالنصر."], ["إذ يغشّيكم النعاس", "يغطّيكم به، والنعاس: نوم خفيف جداً."], ["أمنة", "أمناً من الخوف الذي أصابكم لقلّتكم وكثرة عدوكم."], ["رجز الشيطان", "وسواسه لكم بما يؤلمكم ويحزنكم."], ["وليربط على قلوبكم", "يشدّ عليها بالصبر واليقين."], ["ويثبّت به الأقدام", "بالمطر، حتى لا تسوخ في الرمال."], ["الرعب", "الخوف والفزع."], ["فاضربوا منهم كل بنان", "أطراف اليدين والرجلين حتى يعوقهم عن الضرب والفرار."], ["شاقّوا الله ورسوله", "خالفوه في مراده منهم فلم يطيعوه، وخالفوا رسوله."], ["ذلكم فذوقوه", "أي العذاب فذوقوه."], ["عذاب النار", "أي في الآخرة."]], "m": "ما زال السياق في غزوة بدر ونعمها: اذكروا إذ كنتم خائفين لقلّتكم وكثرة عدوكم فاستغثتم ربكم: اللهم نصرك، اللهم أنجز لي ما وعدتني، فاستجاب لكم: أني ممدّكم بألف من الملائكة مردفين متتابعين، وما جعله الله إلا بشرى لكم ولتطمئن به قلوبكم، أما النصر فمن عند الله، إن الله عزيز حكيم. ونعمة ثانية: إذ يغشّيكم النعاس أمنة منه، فإن العبد إذا خامره النعاس هدأ وسكن وذهب عنه الخوف فثبت. ونعمة أخرى: كانت الأرض رملية تسوخ فيها أقدامهم، وقلّ ماؤهم فصاروا عطاشاً محدثين، ووسوس الشيطان لبعضهم: تقاتلون محدثين عطاشاً وعدوكم ريّان، فأنزل الله على معسكرهم خاصة مطراً غزيراً شربوا منه وتطهّروا، وتلبّدت به التربة، وذهب رجز الشيطان، وربط على قلوبهم بالصبر واليقين، وثبّت به الأقدام. ونعمة أخرى: إذ يوحي ربك إلى الملائكة: أني معكم فثبّتوا الذين آمنوا بالكلام المشجّع، سألقي في قلوب الذين كفروا الرعب، فاضربوا فوق الأعناق، واضربوا منهم كل بنان. ذلك بأنهم عادوا الله ورسوله، ومن يشاقق الله ورسوله فإن الله شديد العقاب، ذلكم القتل والهزيمة فذوقوه في الدنيا، وأن للكافرين في الآخرة عذاب النار.", "h": ["مشروعية الاستغاثة بالله تعالى، وهي عبادة، فلا يصح أن يُستغاث بغير الله تعالى.", "تقرير عقيدة أن الملائكة عباد لله يسخّرهم في فعل ما يشاء، وقد سخّرهم للقتال مع المؤمنين فقاتلوا ونصروا وثبّتوا، وذلك بأمر الله تعالى لهم.", "تعداد نعم الله تعالى على المؤمنين في غزوة بدر، وهي كثيرة.", "مشاقّة الله ورسوله كفر يستوجب صاحبها عذاب الدنيا وعذاب الآخرة.", "تعليم الله تعالى عباده كيف يقاتلون ويضربون أعداءهم، وهذا شرف كبير للمؤمنين."], "k": "«إذ تستغيثون ربكم فاستجاب لكم»… في ضيقي، إلى من أستغيث أولاً؟"}, {"lbl": "الآيات ١٥ – ١٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ زَحۡفٗا فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ ﴿١٥﴾ وَمَن يُوَلِّهِمۡ يَوۡمَئِذٖ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفٗا لِّقِتَالٍ أَوۡ مُتَحَيِّزًا إِلَىٰ فِئَةٖ فَقَدۡ بَآءَ بِغَضَبٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿١٦﴾ فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿١٧﴾ ذَٰلِكُمۡ وَأَنَّ ٱللَّهَ مُوهِنُ كَيۡدِ ٱلۡكَٰفِرِينَ ﴿١٨﴾ إِن تَسۡتَفۡتِحُواْ فَقَدۡ جَآءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُواْ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَعُودُواْ نَعُدۡ وَلَن تُغۡنِيَ عَنكُمۡ فِئَتُكُمۡ شَيۡـٔٗا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِينَ ﴿١٩﴾", "w": [["زحفاً", "زاحفين لكثرتهم وبطء سيرهم، كأنهم يزحفون على الأرض."], ["متحرّفاً لقتال", "مائلاً من جهة إلى أخرى ليتمكّن من ضرب العدو وقتاله."], ["أو متحيّزاً إلى فئة", "يريد الانحياز إلى جماعة من المؤمنين تقاتل."], ["فقد باء بغضب", "رجع من المعركة مصحوباً بغضب من الله لمعصيته."], ["وليُبلي المؤمنين", "لينعم عليهم بنعمة النصر والظفر على قلة عددهم."], ["فئتكم", "مقاتلتكم من رجالكم الكثيرين."]], "m": "ينادي الرب المؤمنين: إذا لقيتم الذين كفروا زاحفين إليكم فلا تولّوهم الأدبار، فلا تنهزموا أمامهم فتمكّنوهم من قتلكم، ومن يولّهم يومئذ دبره إلا متحرّفاً لقتال ليتمكّن من عدوه، أو متحيّزاً إلى فئة من المؤمنين تقاتل، فقد باء بغضب من الله، ومأواه جهنم وبئس المصير. فلم تقتلوهم ولكن الله قتلهم، فهو الذي أمركم وأقدركم وأعانكم، حتى لا يخطر ببالكم أنكم المقاتلون وحدكم، وما رميت إذ رميت ولكن الله رمى، فحثية التراب التي رماها الرسول ﷺ وصلت إلى جلّ أعين المشركين فأذهلتهم وعوّقتهم عن القتال، والله هو الذي أوصلها، وليُبلي المؤمنين منه بلاءً حسناً بنصرهم في الدنيا وإدخالهم الجنة في الآخرة، إن الله سميع لاستغاثتهم، عليم بضعفهم. ذلكم، وأن الله موهن كيد الكافرين، فكلما كادوا لأوليائه أضعفه وأبطله. وقال أبو جهل وغيره: اللهم أيّنا كان أقطع للرحم وأتانا بما لا نعرف فأحِنه الغداة، فقال الله: إن تستفتحوا، تطلبوا القضاء بينكم وبين محمد، فقد جاءكم الفتح بهزيمتكم في بدر، وإن تنتهوا عن الحرب وتُسلموا فهو خير لكم، وإن تعودوا نعد فنسلّط عليكم رسولنا والمؤمنين، ولن تغني عنكم فئتكم شيئاً ولو كثرت، وأن الله مع المؤمنين ما استقاموا على طاعته.", "h": ["حرمة الفرار من العدو الكافر عند اللقاء، لما توعّد الله عليه من الغضب والعذاب، ولعدّ الرسول ﷺ له من الموبقات السبع في حديث مسلم: «والتولّي يوم الزحف».", "تقرير مبدأ أن الله تعالى خالق كل شيء، وأنه خلق العبد وخلق فعله، إذ لما كان العبد مخلوقاً وقدرته مخلوقة، ولا يصدر منه فعل ولا قول إلا بإقدار الله له، كان الفاعل الحقيقي هو الله، وما للعبد إلا الكسب بجوارحه، وبذلك يُجزى الخير بالخير والشر بمثله.", "آية وصول حثية التراب من كف الرسول ﷺ إلى أغلب عيون المشركين في المعركة.", "إكرام الله تعالى وإبلاؤه لأوليائه البلاء الحسن، فله الحمد وله المنّة.", "ولاية الله للمؤمنين الصادقين هي أسباب نصرهم وكمالهم وإسعادهم."], "k": "«وما رميت إذ رميت ولكن الله رمى»… حين أنجح في أمر، هل أنسبه لنفسي أم لتوفيق ربي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (115, 8, 20, 29, 'سورة الأنفال ٢٠ – ٢٩', '«استجيبوا لله وللرسول إذا دعاكم لما يحييكم»، و«إن تتقوا الله يجعل لكم فرقاناً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 115) = $j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوۡاْ عَنۡهُ وَأَنتُمۡ تَسۡمَعُونَ ﴿٢٠﴾ وَلَا تَكُونُواْ كَٱلَّذِينَ قَالُواْ سَمِعۡنَا وَهُمۡ لَا يَسۡمَعُونَ ﴿٢١﴾ ۞إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِينَ لَا يَعۡقِلُونَ ﴿٢٢﴾ وَلَوۡ عَلِمَ ٱللَّهُ فِيهِمۡ خَيۡرٗا لَّأَسۡمَعَهُمۡۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ ﴿٢٣﴾", "w": [["ولا تولّوا عنه", "لا تُعرضوا عنه وأنتم تسمعون آياته."], ["إن شر الدواب", "شر ما يدبّ على الأرض: الكافرون."], ["الصم البكم", "الذين لا يسمعون الحق ولا ينطقون به."]], "m": "والعظات تتوالى لأن نصركم كان ثمرة إيمانكم وطاعتكم، فإن أعرضتم وعصيتم أصبحتم كغيركم: يا أيها الذين آمنوا أطيعوا الله ورسوله ولا تولّوا عنه وأنتم تسمعون، ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون، من المشركين الذين تصاموا عن سماع الآيات وتعاموا عن رؤيتها، فهم يقولون: سمعنا بآذاننا، ولا يتدبّرون بقلوبهم، والعبرة بالسماع الانتفاع به لا مجرد سماع الصوت. إن شر الدواب عند الله الصم البكم الذين لا يعقلون، يعني المشركين، كفروا وظلموا وأجرموا، فهم حقاً شر الدواب، وفيه تحذير للمؤمنين من معصية الله ورسوله. ولو علم الله فيهم خيراً لأسمعهم الآيات وما فيها، ولو أسمعهم لتولّوا وهم معرضون، طائفة توغّلت في الشر والكبر والعناد فحُرمت الهداية، هلك بعضهم في بدر وبعضهم في أحد ولم يؤمنوا، لعلم الله أنه لا خير فيهم، ألا يعلم من خلق وهو اللطيف الخبير؟", "h": ["وجوب طاعة الله ورسوله في أمرهما ونهيهما، وحرمة معصيتهما.", "حرمة التشبّه بالمشركين والكافرين وسائر أهل الضلال في كل شيء من سلوكهم.", "بيان أن من الناس من هو شر من الكلاب والخنازير فضلاً عن الإبل والبقر والغنم، أولئك الذين كفروا وظلموا، لم يكن الله ليغفر لهم ولا ليهديهم سبيلاً."], "k": "«قالوا سمعنا وهم لا يسمعون»… كم آية سمعتها اليوم، وكم منها نزلت إلى قلبي؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَحُولُ بَيۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ وَأَنَّهُۥٓ إِلَيۡهِ تُحۡشَرُونَ ﴿٢٤﴾ وَٱتَّقُواْ فِتۡنَةٗ لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُواْ مِنكُمۡ خَآصَّةٗۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٢٥﴾ وَٱذۡكُرُوٓاْ إِذۡ أَنتُمۡ قَلِيلٞ مُّسۡتَضۡعَفُونَ فِي ٱلۡأَرۡضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمۡ وَأَيَّدَكُم بِنَصۡرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٢٦﴾", "w": [["استجيبوا", "اسمعوا وأطيعوا."], ["لما يحييكم", "لما فيه حياتكم، ولما هو سبب في حياتكم، كالإيمان والعمل الصالح والجهاد."], ["فتنة", "عذاباً تُفتنون به، كالقحط أو المرض أو تسلّط عدو."], ["مستضعفون", "ضعفاء أمام أعدائكم، يرونكم ضعفاء فينالون منكم."], ["ورزقكم من الطيبات", "جمع طيب، من سائر المحلّلات من المطاعم والمشارب."], ["لعلكم تشكرون", "رجاء أن تشكروه تعالى بصرف النعمة في مرضاته."]], "m": "هذا النداء الثالث بالكرامة: يا أيها الذين آمنوا استجيبوا لله وللرسول إذا دعاكم لما يحييكم، إشعار بأن أوامر الله ورسوله ونواهيهما لا تخلو أبداً مما يحيي المؤمنين أو يزيد في حياتهم أو يحفظها عليهم. واعلموا أن الله يحول بين المرء وقلبه، تنبيه عظيم: إذا سنحت لهم فرصة للخير فليغتنموها قبل الفوات، لا سيما إذا كانت دعوة من الله ورسوله، لأن الله قادر على أن يقلّب القلب فيكره الخير ويرغب في الشر، وأنه إليه تُحشرون، فكيف يسوغ لمن يعلم ذلك أن يُعرض عن ندائه؟ واتقوا فتنة لا تصيبنّ الذين ظلموا منكم خاصة، تحذير من ترك الطاعة وترك الأمر بالمعروف والنهي عن المنكر، فينتشر الشر وينزل البلاء فيعمّ الصالح والطالح، واعلموا أن الله شديد العقاب. واذكروا إذ أنتم قليل مستضعفون في الأرض بمكة تخافون أن يتخطّفكم الناس، فآواكم إلى المدينة، وأيّدكم بنصره فعززتم بعد ذلة، ورزقكم من الطيبات، لعلكم تشكرون، والله يعلم أنهم قد شكروا فرضي عنهم.", "h": ["وجوب الاستجابة لنداء الله ورسوله بفعل الأمر وترك النهي، لما في ذلك من حياة الفرد والأمة.", "تعيّن اغتنام فرصة الخير قبل فواتها، فمتى سنحت للمؤمن تعيّن عليه اغتنامها.", "وجوب الأمر بالمعروف والنهي عن المنكر، اتقاء للفتن العامة التي يهلك فيها العادل والظالم.", "وجوب ذكر النعم لشكرها بطاعة الله ورسوله ﷺ.", "وجوب شكر النعم بحمد الله تعالى والثناء عليه، والاعتراف بالنعمة له، والتصرّف فيها في مرضاته."], "k": "«أن الله يحول بين المرء وقلبه»… فرصة خير أمامي الآن؛ هل أؤجّلها وقلبي قد يتغيّر؟"}, {"lbl": "الآيات ٢٧ – ٢٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَخُونُواْ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓاْ أَمَٰنَٰتِكُمۡ وَأَنتُمۡ تَعۡلَمُونَ ﴿٢٧﴾ وَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ﴿٢٨﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا وَيُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٢٩﴾", "w": [["لا تخونوا الله والرسول", "بإظهار الإيمان والطاعة ومخالفتهما في الباطن."], ["وتخونوا أماناتكم", "ولا تخونوا أماناتكم التي يأتمن عليها بعضكم بعضاً."], ["إنما أموالكم وأولادكم فتنة", "الاشتغال بذلك يفتنكم عن طاعة الله ورسوله."], ["إن تتقوا الله", "بامتثال أمره واجتناب نهيه في المعتقد والقول والعمل."], ["يجعل لكم فرقاناً", "نوراً في بصائركم تفرّقون به بين النافع والضار، والصالح والفاسد."], ["ويكفّر عنكم سيئاتكم", "يمحو عنكم ما سلف من ذنوبكم التي بينكم وبينه."]], "m": "نداء رباني آخر: يا أيها الذين آمنوا لا تخونوا الله والرسول بأن يُظهر أحدكم الطاعة ويستسرّ المعصية، وتخونوا أماناتكم التي يأتمن بعضكم بعضاً عليها، وأنتم تعلمون عظيم جريمة الخيانة وآثارها على النفس والمجتمع. واعلموا أنما أموالكم وأولادكم فتنة، إشارة إلى السبب الحامل غالباً على الخيانة، وأن ما يُرجى من مال أو ولد ليس بشيء بالنسبة إلى ما عند الله، وأن الله عنده أجر عظيم لمن أطاعه وحافظ على أمانته. يا أيها الذين آمنوا إن تتقوا الله يجعل لكم فرقاناً، حضّ على التقوى بذكر أعظم نتائجها: أولاً الفرقان، وهو النصر والفصل بين كل مشتبه والتمييز بين الحق والباطل والضار والنافع، وثانياً تكفير السيئات، وثالثاً مغفرة الذنوب، ورابعاً الأجر العظيم الذي هو الجنة، والله ذو الفضل العظيم.", "h": ["تحريم الخيانة مطلقاً، وأسوؤها ما كان خيانة لله ورسوله.", "في المال والأولاد فتنة قد تحمل على خيانة الله ورسوله، فليحذرها المؤمن.", "من ثمرات التقوى: تكفير السيئات، وغفران الذنوب، والفرقان، وهو نور في القلب يفرّق به المتقي بين الأمور المتشابهات التي خفي فيها وجه الحق والخير."], "k": "«إنما أموالكم وأولادكم فتنة»… هل دفعني حبي لمالي أو أولادي يوماً إلى خيانة أمانة أو تفريط في طاعة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 115;
insert into public.tdb_cards(topic, i, body) select 115, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوۡاْ عَنۡهُ وَأَنتُمۡ تَسۡمَعُونَ ﴿٢٠﴾ وَلَا تَكُونُواْ كَٱلَّذِينَ قَالُواْ سَمِعۡنَا وَهُمۡ لَا يَسۡمَعُونَ ﴿٢١﴾ ۞إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِينَ لَا يَعۡقِلُونَ ﴿٢٢﴾ وَلَوۡ عَلِمَ ٱللَّهُ فِيهِمۡ خَيۡرٗا لَّأَسۡمَعَهُمۡۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ ﴿٢٣﴾", "w": [["ولا تولّوا عنه", "لا تُعرضوا عنه وأنتم تسمعون آياته."], ["إن شر الدواب", "شر ما يدبّ على الأرض: الكافرون."], ["الصم البكم", "الذين لا يسمعون الحق ولا ينطقون به."]], "m": "والعظات تتوالى لأن نصركم كان ثمرة إيمانكم وطاعتكم، فإن أعرضتم وعصيتم أصبحتم كغيركم: يا أيها الذين آمنوا أطيعوا الله ورسوله ولا تولّوا عنه وأنتم تسمعون، ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون، من المشركين الذين تصاموا عن سماع الآيات وتعاموا عن رؤيتها، فهم يقولون: سمعنا بآذاننا، ولا يتدبّرون بقلوبهم، والعبرة بالسماع الانتفاع به لا مجرد سماع الصوت. إن شر الدواب عند الله الصم البكم الذين لا يعقلون، يعني المشركين، كفروا وظلموا وأجرموا، فهم حقاً شر الدواب، وفيه تحذير للمؤمنين من معصية الله ورسوله. ولو علم الله فيهم خيراً لأسمعهم الآيات وما فيها، ولو أسمعهم لتولّوا وهم معرضون، طائفة توغّلت في الشر والكبر والعناد فحُرمت الهداية، هلك بعضهم في بدر وبعضهم في أحد ولم يؤمنوا، لعلم الله أنه لا خير فيهم، ألا يعلم من خلق وهو اللطيف الخبير؟", "h": ["وجوب طاعة الله ورسوله في أمرهما ونهيهما، وحرمة معصيتهما.", "حرمة التشبّه بالمشركين والكافرين وسائر أهل الضلال في كل شيء من سلوكهم.", "بيان أن من الناس من هو شر من الكلاب والخنازير فضلاً عن الإبل والبقر والغنم، أولئك الذين كفروا وظلموا، لم يكن الله ليغفر لهم ولا ليهديهم سبيلاً."], "k": "«قالوا سمعنا وهم لا يسمعون»… كم آية سمعتها اليوم، وكم منها نزلت إلى قلبي؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَحُولُ بَيۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ وَأَنَّهُۥٓ إِلَيۡهِ تُحۡشَرُونَ ﴿٢٤﴾ وَٱتَّقُواْ فِتۡنَةٗ لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُواْ مِنكُمۡ خَآصَّةٗۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ﴿٢٥﴾ وَٱذۡكُرُوٓاْ إِذۡ أَنتُمۡ قَلِيلٞ مُّسۡتَضۡعَفُونَ فِي ٱلۡأَرۡضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمۡ وَأَيَّدَكُم بِنَصۡرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٢٦﴾", "w": [["استجيبوا", "اسمعوا وأطيعوا."], ["لما يحييكم", "لما فيه حياتكم، ولما هو سبب في حياتكم، كالإيمان والعمل الصالح والجهاد."], ["فتنة", "عذاباً تُفتنون به، كالقحط أو المرض أو تسلّط عدو."], ["مستضعفون", "ضعفاء أمام أعدائكم، يرونكم ضعفاء فينالون منكم."], ["ورزقكم من الطيبات", "جمع طيب، من سائر المحلّلات من المطاعم والمشارب."], ["لعلكم تشكرون", "رجاء أن تشكروه تعالى بصرف النعمة في مرضاته."]], "m": "هذا النداء الثالث بالكرامة: يا أيها الذين آمنوا استجيبوا لله وللرسول إذا دعاكم لما يحييكم، إشعار بأن أوامر الله ورسوله ونواهيهما لا تخلو أبداً مما يحيي المؤمنين أو يزيد في حياتهم أو يحفظها عليهم. واعلموا أن الله يحول بين المرء وقلبه، تنبيه عظيم: إذا سنحت لهم فرصة للخير فليغتنموها قبل الفوات، لا سيما إذا كانت دعوة من الله ورسوله، لأن الله قادر على أن يقلّب القلب فيكره الخير ويرغب في الشر، وأنه إليه تُحشرون، فكيف يسوغ لمن يعلم ذلك أن يُعرض عن ندائه؟ واتقوا فتنة لا تصيبنّ الذين ظلموا منكم خاصة، تحذير من ترك الطاعة وترك الأمر بالمعروف والنهي عن المنكر، فينتشر الشر وينزل البلاء فيعمّ الصالح والطالح، واعلموا أن الله شديد العقاب. واذكروا إذ أنتم قليل مستضعفون في الأرض بمكة تخافون أن يتخطّفكم الناس، فآواكم إلى المدينة، وأيّدكم بنصره فعززتم بعد ذلة، ورزقكم من الطيبات، لعلكم تشكرون، والله يعلم أنهم قد شكروا فرضي عنهم.", "h": ["وجوب الاستجابة لنداء الله ورسوله بفعل الأمر وترك النهي، لما في ذلك من حياة الفرد والأمة.", "تعيّن اغتنام فرصة الخير قبل فواتها، فمتى سنحت للمؤمن تعيّن عليه اغتنامها.", "وجوب الأمر بالمعروف والنهي عن المنكر، اتقاء للفتن العامة التي يهلك فيها العادل والظالم.", "وجوب ذكر النعم لشكرها بطاعة الله ورسوله ﷺ.", "وجوب شكر النعم بحمد الله تعالى والثناء عليه، والاعتراف بالنعمة له، والتصرّف فيها في مرضاته."], "k": "«أن الله يحول بين المرء وقلبه»… فرصة خير أمامي الآن؛ هل أؤجّلها وقلبي قد يتغيّر؟"}, {"lbl": "الآيات ٢٧ – ٢٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَخُونُواْ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓاْ أَمَٰنَٰتِكُمۡ وَأَنتُمۡ تَعۡلَمُونَ ﴿٢٧﴾ وَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ﴿٢٨﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا وَيُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٢٩﴾", "w": [["لا تخونوا الله والرسول", "بإظهار الإيمان والطاعة ومخالفتهما في الباطن."], ["وتخونوا أماناتكم", "ولا تخونوا أماناتكم التي يأتمن عليها بعضكم بعضاً."], ["إنما أموالكم وأولادكم فتنة", "الاشتغال بذلك يفتنكم عن طاعة الله ورسوله."], ["إن تتقوا الله", "بامتثال أمره واجتناب نهيه في المعتقد والقول والعمل."], ["يجعل لكم فرقاناً", "نوراً في بصائركم تفرّقون به بين النافع والضار، والصالح والفاسد."], ["ويكفّر عنكم سيئاتكم", "يمحو عنكم ما سلف من ذنوبكم التي بينكم وبينه."]], "m": "نداء رباني آخر: يا أيها الذين آمنوا لا تخونوا الله والرسول بأن يُظهر أحدكم الطاعة ويستسرّ المعصية، وتخونوا أماناتكم التي يأتمن بعضكم بعضاً عليها، وأنتم تعلمون عظيم جريمة الخيانة وآثارها على النفس والمجتمع. واعلموا أنما أموالكم وأولادكم فتنة، إشارة إلى السبب الحامل غالباً على الخيانة، وأن ما يُرجى من مال أو ولد ليس بشيء بالنسبة إلى ما عند الله، وأن الله عنده أجر عظيم لمن أطاعه وحافظ على أمانته. يا أيها الذين آمنوا إن تتقوا الله يجعل لكم فرقاناً، حضّ على التقوى بذكر أعظم نتائجها: أولاً الفرقان، وهو النصر والفصل بين كل مشتبه والتمييز بين الحق والباطل والضار والنافع، وثانياً تكفير السيئات، وثالثاً مغفرة الذنوب، ورابعاً الأجر العظيم الذي هو الجنة، والله ذو الفضل العظيم.", "h": ["تحريم الخيانة مطلقاً، وأسوؤها ما كان خيانة لله ورسوله.", "في المال والأولاد فتنة قد تحمل على خيانة الله ورسوله، فليحذرها المؤمن.", "من ثمرات التقوى: تكفير السيئات، وغفران الذنوب، والفرقان، وهو نور في القلب يفرّق به المتقي بين الأمور المتشابهات التي خفي فيها وجه الحق والخير."], "k": "«إنما أموالكم وأولادكم فتنة»… هل دفعني حبي لمالي أو أولادي يوماً إلى خيانة أمانة أو تفريط في طاعة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (116, 8, 30, 40, 'سورة الأنفال ٣٠ – ٤٠', '«ويمكرون ويمكر الله»، «وما كان الله ليعذّبهم وأنت فيهم»، و«قل للذين كفروا إن ينتهوا يُغفر لهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 116) = $j$[{"lbl": "الآيتان ٣٠ – ٣١", "q": "وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ كَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَۚ وَيَمۡكُرُونَ وَيَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ ﴿٣٠﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا قَالُواْ قَدۡ سَمِعۡنَا لَوۡ نَشَآءُ لَقُلۡنَا مِثۡلَ هَٰذَآ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٣١﴾", "w": [["وإذ يمكر بك", "يبيّتون لك ما يضرّك."], ["ليثبتوك", "ليحبسوك مثبتاً بوثاق حتى لا تفرّ من الحبس."], ["أو يخرجوك", "ينفوك بعيداً عن ديارهم."], ["ويمكرون ويمكر الله", "يدبّرون لك السوء ويبيّتون لك المكروه، والله يدبّر لهم ما يضرّهم ويبيّت لهم ما يسوؤهم."], ["آياتنا", "آيات القرآن الكريم."], ["أساطير الأولين", "الأساطير جمع أسطورة: ما يُدوّن ويُسطّر من أخبار الأولين."]], "m": "يذكّر الله رسوله والمؤمنين بنعمة من نعمه: واذكر إذ يمكر بك الذين كفروا ليثبتوك أو يقتلوك أو يخرجوك، إذ اجتمعت قريش في دار الندوة وائتمرت في شأن النبي ﷺ، فأصدروا حكمهم بقتله، وبعثوا من ينفّذ الجريمة فطوّقوا منزله، فخرج ﷺ بعد أن رماهم بحثية من تراب قائلاً: «شاهت الوجوه»، فلم يره أحد، وهاجر إلى المدينة، ويمكرون ويمكر الله والله خير الماكرين، فكانت نجاته نعمة عظمى عليه وعلى سائر المؤمنين. وإذا تُتلى عليهم آياتنا المقرّرة للإيمان قالوا: قد سمعنا، لو نشاء لقلنا مثل هذا، إن هذا إلا أساطير الأولين، أخبار السابقين سُطّرت فهي تُملى عليك فتحفظها، وكان قائل هذه المقالة النضر بن الحارث، مات كافراً.", "h": ["التذكير بنعم الله تعالى على العبد ليجد العبد في نفسه داعية الشكر فيشكر.", "بيان مدى ما قاومت به قريش دعوة الإسلام، حتى إنها أصدرت حكمها بقتل الرسول ﷺ.", "بيان موقف المشركين من الدعوة الإسلامية، وأنهم بذلوا كل جهد في سبيل إنهائها والقضاء عليها."], "k": "«ويمكرون ويمكر الله والله خير الماكرين»… حين يكيد لي أحد، هل أطمئن أن تدبير ربي فوق كل تدبير؟"}, {"lbl": "الآيات ٣٢ – ٣٥", "q": "وَإِذۡ قَالُواْ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَةٗ مِّنَ ٱلسَّمَآءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِيمٖ ﴿٣٢﴾ وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمۡ وَأَنتَ فِيهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ ﴿٣٣﴾ وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٣٤﴾ وَمَا كَانَ صَلَاتُهُمۡ عِندَ ٱلۡبَيۡتِ إِلَّا مُكَآءٗ وَتَصۡدِيَةٗۚ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿٣٥﴾", "w": [["اللهم", "يا الله، حُذفت ياء النداء من أوله، وعُوّض عنها الميم في آخره."], ["إن كان هذا", "أي الذي جاء به محمد ويخبر به."], ["فأمطر", "أنزل علينا حجارة."], ["يصدّون عن المسجد الحرام", "يمنعون الناس من الدخول إليه للاعتمار."], ["مكاء وتصدية", "المكاء: التصفير، والتصدية: التصفيق."]], "m": "ما زال السياق في التنديد بأقوال المشركين: قال النضر بن الحارث: اللهم إن كان هذا القرآن هو الحق من عندك فأمطر علينا حجارة من السماء فنهلك ولا نرى محمداً ينتصر دينه، أو ائتنا بعذاب أليم. فقال الله: وما كان الله ليعذّبهم وأنت فيهم، فوجودك بينهم أمان لهم، وما كان الله معذّبهم وهم يستغفرون، إذ كان بعضهم يقول في طوافه: غفرانك ربنا غفرانك. وما لهم ألا يعذّبهم الله وهم يصدّون الناس عن دخول المسجد الحرام للطواف والصلاة؟ وما كانوا أولياءه كما يزعمون أنهم ولاته، فيمنعون من شاؤوا، إن أولياؤه إلا المتقون الذين يتقون الشرك والمعاصي، ولكن أكثرهم لا يعلمون، لجهل بعضهم وعناد آخرين. وما كان صلاتهم عند البيت إلا مكاء وتصدية، إذ كان بعضهم إذا طافوا يصفّقون ويصفّرون، فذوقوا العذاب بما كنتم تكفرون، أذاقهموه يوم بدر فأذلّهم وأخزاهم وقتل رؤساءهم.", "h": ["بيان ما كان عليه المشركون في مكة من بغض للحق وكراهية له، حتى سألوا العذاب العام ولا يرون راية الحق تظهر ودين الله ينتصر.", "النبي ﷺ أمان أمته من العذاب، فلم تُصب هذه الأمة بعذاب الاستئصال والإبادة.", "فضيلة الاستغفار، وأنه ينجي من عذاب الدنيا والآخرة.", "بيان عظم جرم من يصدّ عن المسجد الحرام للعبادة الشرعية فيه.", "بيان أولياء الله تعالى والذين يحق لهم أن يلوا المسجد الحرام، وهم المتقون.", "كراهية الصفير والتصفيق، وبطلان الرقص في التعبّد."], "k": "«وما كان الله معذّبهم وهم يستغفرون»… الاستغفار أمان باقٍ لي؛ فكم مرة استغفرت اليوم؟"}, {"lbl": "الآيتان ٣٦ – ٣٧", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ يُنفِقُونَ أَمۡوَٰلَهُمۡ لِيَصُدُّواْ عَن سَبِيلِ ٱللَّهِۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيۡهِمۡ حَسۡرَةٗ ثُمَّ يُغۡلَبُونَۗ وَٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ يُحۡشَرُونَ ﴿٣٦﴾ لِيَمِيزَ ٱللَّهُ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجۡعَلَ ٱلۡخَبِيثَ بَعۡضَهُۥ عَلَىٰ بَعۡضٖ فَيَرۡكُمَهُۥ جَمِيعٗا فَيَجۡعَلَهُۥ فِي جَهَنَّمَۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٣٧﴾", "w": [["إن الذين كفروا", "كذّبوا بآيات الله ورسالة رسوله محمد ﷺ من قريش."], ["ثم تكون عليهم حسرة", "شدة ندامة."], ["ثم يُغلبون", "يُهزمون."], ["الخبيث", "أهل الشرك والمعاصي."], ["من الطيب", "أهل التوحيد والأعمال الصالحة."], ["فيركمه", "يجعل بعضه فوق بعض في جهنم."]], "m": "إن الذين كفروا من زعماء قريش ينفقون أموالهم في حرب رسول الله والمؤمنين ليصدّوا عن سبيل الله، الإسلام، فسينفقونها ثم تكون عليهم حسرة وندامة شديدة لسوء العاقبة في بدر وأحد والخندق، أنفقوا عليها ما الله به عليم ثم خابوا، ثم يُغلبون، وانتهى سلطانهم وفتح الله مكة. والذين ماتوا منهم على الكفر إلى جهنم يُحشرون، ليميز الله الخبيث من الطيب: فالطيبون الصالحون يعبرون الصراط إلى الجنة، والخبيث فريق المشركين يجعل بعضه على بعض فيركمه جميعاً كوماً واحداً فيجعله في جهنم، أولئك هم الخاسرون بحق: خسروا أنفسهم وأموالهم وأهليهم وكل شيء.", "h": ["كل نفقة ينفقها العبد للصد عن سبيل الله بأي وجه من الوجوه تكون عليه حسرة عظيمة.", "كل كافر خبيث، وكل مؤمن طيب.", "صدق وعد الله تعالى لرسوله والمؤمنين بهزيمة المشركين وغلبتهم، وحسرتهم على ما أنفقوا في حرب الإسلام، وضياع ذلك كله، وخيبتهم فيه."], "k": "«ليميز الله الخبيث من الطيب»… في أي الفريقين يضعني مالي ووقتي الذي أنفقه؟"}, {"lbl": "الآيات ٣٨ – ٤٠", "q": "قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ وَإِن يَعُودُواْ فَقَدۡ مَضَتۡ سُنَّتُ ٱلۡأَوَّلِينَ ﴿٣٨﴾ وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِۚ فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ بَصِيرٞ ﴿٣٩﴾ وَإِن تَوَلَّوۡاْ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ ﴿٤٠﴾", "w": [["إن ينتهوا", "عن الكفر بالله ورسوله، وحرب الرسول والمؤمنين."], ["ما قد سلف", "ما مضى من ذنوبهم من الشرك وحرب الرسول والمؤمنين."], ["مضت سنّة الأولين", "في إهلاك الظالمين."], ["لا تكون فتنة", "أي شرك بالله، واضطهاد وتعذيب في سبيل الله."], ["ويكون الدين كله لله", "حتى لا يُعبد غير الله."], ["مولاكم", "متولّي أمركم بالنصر والتأييد."]], "m": "ما زال السياق في بيان الإجراءات الواجبة إزاء الكافرين: قل للذين كفروا مبلّغاً عنا: إن ينتهوا عن الشرك وحرب الإسلام وأهله يُغفر لهم ما قد سلف من ذنوبهم العظام، وعد صدق ممن لا يخلف الوعد، وإن يعودوا إلى الظلم والحرب فقد مضت سنّة الأولين: أخذهم بعد الإنذار والإعذار. ثم أمر بقتال المشركين قتالاً متواصلاً حتى لا تكون فتنة، أي شرك ولا اضطهاد لمؤمن من أجل دينه، ويكون الدين كله لله فلا يُعبد معه أحد، فإن انتهوا عن الشرك والظلم فكفّوا عنهم، وإن انتهوا في الظاهر دون الباطن فلا يضرّكم، فإن الله بما يعملون بصير وسيُظهركم عليهم، وإن تولّوا ونكثوا وعادوا إلى حربكم فقاتلوهم، واعلموا أن الله مولاكم فلا يسلّطهم عليكم، نعم المولى لمن تولّاه ونعم النصير لمن نصره.", "h": ["بيان سعة فضل الله ورحمته.", "الإسلام يجُبّ، أي يقطع ما قبله، فيغفر لمن أسلم كل ذنب قارفه من الكفر وغيره.", "بيان سنة الله في الظالمين، وهي إهلاكهم وإن طالت مدة الإملاء والإنظار.", "وجوب قتال المشركين على المسلمين ما بقي في الأرض مشرك.", "نعم المولى الله جل جلاله لمن تولّاه، ونعم النصير لمن نصره."], "k": "«إن ينتهوا يُغفر لهم ما قد سلف»… إن كان هذا وعده للمحاربين، فكيف بعبد مؤمن يرجع إليه نادماً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 116;
insert into public.tdb_cards(topic, i, body) select 116, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٣٠ – ٣١", "q": "وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ كَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَۚ وَيَمۡكُرُونَ وَيَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ ﴿٣٠﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا قَالُواْ قَدۡ سَمِعۡنَا لَوۡ نَشَآءُ لَقُلۡنَا مِثۡلَ هَٰذَآ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٣١﴾", "w": [["وإذ يمكر بك", "يبيّتون لك ما يضرّك."], ["ليثبتوك", "ليحبسوك مثبتاً بوثاق حتى لا تفرّ من الحبس."], ["أو يخرجوك", "ينفوك بعيداً عن ديارهم."], ["ويمكرون ويمكر الله", "يدبّرون لك السوء ويبيّتون لك المكروه، والله يدبّر لهم ما يضرّهم ويبيّت لهم ما يسوؤهم."], ["آياتنا", "آيات القرآن الكريم."], ["أساطير الأولين", "الأساطير جمع أسطورة: ما يُدوّن ويُسطّر من أخبار الأولين."]], "m": "يذكّر الله رسوله والمؤمنين بنعمة من نعمه: واذكر إذ يمكر بك الذين كفروا ليثبتوك أو يقتلوك أو يخرجوك، إذ اجتمعت قريش في دار الندوة وائتمرت في شأن النبي ﷺ، فأصدروا حكمهم بقتله، وبعثوا من ينفّذ الجريمة فطوّقوا منزله، فخرج ﷺ بعد أن رماهم بحثية من تراب قائلاً: «شاهت الوجوه»، فلم يره أحد، وهاجر إلى المدينة، ويمكرون ويمكر الله والله خير الماكرين، فكانت نجاته نعمة عظمى عليه وعلى سائر المؤمنين. وإذا تُتلى عليهم آياتنا المقرّرة للإيمان قالوا: قد سمعنا، لو نشاء لقلنا مثل هذا، إن هذا إلا أساطير الأولين، أخبار السابقين سُطّرت فهي تُملى عليك فتحفظها، وكان قائل هذه المقالة النضر بن الحارث، مات كافراً.", "h": ["التذكير بنعم الله تعالى على العبد ليجد العبد في نفسه داعية الشكر فيشكر.", "بيان مدى ما قاومت به قريش دعوة الإسلام، حتى إنها أصدرت حكمها بقتل الرسول ﷺ.", "بيان موقف المشركين من الدعوة الإسلامية، وأنهم بذلوا كل جهد في سبيل إنهائها والقضاء عليها."], "k": "«ويمكرون ويمكر الله والله خير الماكرين»… حين يكيد لي أحد، هل أطمئن أن تدبير ربي فوق كل تدبير؟"}, {"lbl": "الآيات ٣٢ – ٣٥", "q": "وَإِذۡ قَالُواْ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَةٗ مِّنَ ٱلسَّمَآءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِيمٖ ﴿٣٢﴾ وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمۡ وَأَنتَ فِيهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ ﴿٣٣﴾ وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٣٤﴾ وَمَا كَانَ صَلَاتُهُمۡ عِندَ ٱلۡبَيۡتِ إِلَّا مُكَآءٗ وَتَصۡدِيَةٗۚ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿٣٥﴾", "w": [["اللهم", "يا الله، حُذفت ياء النداء من أوله، وعُوّض عنها الميم في آخره."], ["إن كان هذا", "أي الذي جاء به محمد ويخبر به."], ["فأمطر", "أنزل علينا حجارة."], ["يصدّون عن المسجد الحرام", "يمنعون الناس من الدخول إليه للاعتمار."], ["مكاء وتصدية", "المكاء: التصفير، والتصدية: التصفيق."]], "m": "ما زال السياق في التنديد بأقوال المشركين: قال النضر بن الحارث: اللهم إن كان هذا القرآن هو الحق من عندك فأمطر علينا حجارة من السماء فنهلك ولا نرى محمداً ينتصر دينه، أو ائتنا بعذاب أليم. فقال الله: وما كان الله ليعذّبهم وأنت فيهم، فوجودك بينهم أمان لهم، وما كان الله معذّبهم وهم يستغفرون، إذ كان بعضهم يقول في طوافه: غفرانك ربنا غفرانك. وما لهم ألا يعذّبهم الله وهم يصدّون الناس عن دخول المسجد الحرام للطواف والصلاة؟ وما كانوا أولياءه كما يزعمون أنهم ولاته، فيمنعون من شاؤوا، إن أولياؤه إلا المتقون الذين يتقون الشرك والمعاصي، ولكن أكثرهم لا يعلمون، لجهل بعضهم وعناد آخرين. وما كان صلاتهم عند البيت إلا مكاء وتصدية، إذ كان بعضهم إذا طافوا يصفّقون ويصفّرون، فذوقوا العذاب بما كنتم تكفرون، أذاقهموه يوم بدر فأذلّهم وأخزاهم وقتل رؤساءهم.", "h": ["بيان ما كان عليه المشركون في مكة من بغض للحق وكراهية له، حتى سألوا العذاب العام ولا يرون راية الحق تظهر ودين الله ينتصر.", "النبي ﷺ أمان أمته من العذاب، فلم تُصب هذه الأمة بعذاب الاستئصال والإبادة.", "فضيلة الاستغفار، وأنه ينجي من عذاب الدنيا والآخرة.", "بيان عظم جرم من يصدّ عن المسجد الحرام للعبادة الشرعية فيه.", "بيان أولياء الله تعالى والذين يحق لهم أن يلوا المسجد الحرام، وهم المتقون.", "كراهية الصفير والتصفيق، وبطلان الرقص في التعبّد."], "k": "«وما كان الله معذّبهم وهم يستغفرون»… الاستغفار أمان باقٍ لي؛ فكم مرة استغفرت اليوم؟"}, {"lbl": "الآيتان ٣٦ – ٣٧", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ يُنفِقُونَ أَمۡوَٰلَهُمۡ لِيَصُدُّواْ عَن سَبِيلِ ٱللَّهِۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيۡهِمۡ حَسۡرَةٗ ثُمَّ يُغۡلَبُونَۗ وَٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ يُحۡشَرُونَ ﴿٣٦﴾ لِيَمِيزَ ٱللَّهُ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجۡعَلَ ٱلۡخَبِيثَ بَعۡضَهُۥ عَلَىٰ بَعۡضٖ فَيَرۡكُمَهُۥ جَمِيعٗا فَيَجۡعَلَهُۥ فِي جَهَنَّمَۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٣٧﴾", "w": [["إن الذين كفروا", "كذّبوا بآيات الله ورسالة رسوله محمد ﷺ من قريش."], ["ثم تكون عليهم حسرة", "شدة ندامة."], ["ثم يُغلبون", "يُهزمون."], ["الخبيث", "أهل الشرك والمعاصي."], ["من الطيب", "أهل التوحيد والأعمال الصالحة."], ["فيركمه", "يجعل بعضه فوق بعض في جهنم."]], "m": "إن الذين كفروا من زعماء قريش ينفقون أموالهم في حرب رسول الله والمؤمنين ليصدّوا عن سبيل الله، الإسلام، فسينفقونها ثم تكون عليهم حسرة وندامة شديدة لسوء العاقبة في بدر وأحد والخندق، أنفقوا عليها ما الله به عليم ثم خابوا، ثم يُغلبون، وانتهى سلطانهم وفتح الله مكة. والذين ماتوا منهم على الكفر إلى جهنم يُحشرون، ليميز الله الخبيث من الطيب: فالطيبون الصالحون يعبرون الصراط إلى الجنة، والخبيث فريق المشركين يجعل بعضه على بعض فيركمه جميعاً كوماً واحداً فيجعله في جهنم، أولئك هم الخاسرون بحق: خسروا أنفسهم وأموالهم وأهليهم وكل شيء.", "h": ["كل نفقة ينفقها العبد للصد عن سبيل الله بأي وجه من الوجوه تكون عليه حسرة عظيمة.", "كل كافر خبيث، وكل مؤمن طيب.", "صدق وعد الله تعالى لرسوله والمؤمنين بهزيمة المشركين وغلبتهم، وحسرتهم على ما أنفقوا في حرب الإسلام، وضياع ذلك كله، وخيبتهم فيه."], "k": "«ليميز الله الخبيث من الطيب»… في أي الفريقين يضعني مالي ووقتي الذي أنفقه؟"}, {"lbl": "الآيات ٣٨ – ٤٠", "q": "قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ وَإِن يَعُودُواْ فَقَدۡ مَضَتۡ سُنَّتُ ٱلۡأَوَّلِينَ ﴿٣٨﴾ وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِۚ فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ بَصِيرٞ ﴿٣٩﴾ وَإِن تَوَلَّوۡاْ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ ﴿٤٠﴾", "w": [["إن ينتهوا", "عن الكفر بالله ورسوله، وحرب الرسول والمؤمنين."], ["ما قد سلف", "ما مضى من ذنوبهم من الشرك وحرب الرسول والمؤمنين."], ["مضت سنّة الأولين", "في إهلاك الظالمين."], ["لا تكون فتنة", "أي شرك بالله، واضطهاد وتعذيب في سبيل الله."], ["ويكون الدين كله لله", "حتى لا يُعبد غير الله."], ["مولاكم", "متولّي أمركم بالنصر والتأييد."]], "m": "ما زال السياق في بيان الإجراءات الواجبة إزاء الكافرين: قل للذين كفروا مبلّغاً عنا: إن ينتهوا عن الشرك وحرب الإسلام وأهله يُغفر لهم ما قد سلف من ذنوبهم العظام، وعد صدق ممن لا يخلف الوعد، وإن يعودوا إلى الظلم والحرب فقد مضت سنّة الأولين: أخذهم بعد الإنذار والإعذار. ثم أمر بقتال المشركين قتالاً متواصلاً حتى لا تكون فتنة، أي شرك ولا اضطهاد لمؤمن من أجل دينه، ويكون الدين كله لله فلا يُعبد معه أحد، فإن انتهوا عن الشرك والظلم فكفّوا عنهم، وإن انتهوا في الظاهر دون الباطن فلا يضرّكم، فإن الله بما يعملون بصير وسيُظهركم عليهم، وإن تولّوا ونكثوا وعادوا إلى حربكم فقاتلوهم، واعلموا أن الله مولاكم فلا يسلّطهم عليكم، نعم المولى لمن تولّاه ونعم النصير لمن نصره.", "h": ["بيان سعة فضل الله ورحمته.", "الإسلام يجُبّ، أي يقطع ما قبله، فيغفر لمن أسلم كل ذنب قارفه من الكفر وغيره.", "بيان سنة الله في الظالمين، وهي إهلاكهم وإن طالت مدة الإملاء والإنظار.", "وجوب قتال المشركين على المسلمين ما بقي في الأرض مشرك.", "نعم المولى الله جل جلاله لمن تولّاه، ونعم النصير لمن نصره."], "k": "«إن ينتهوا يُغفر لهم ما قد سلف»… إن كان هذا وعده للمحاربين، فكيف بعبد مؤمن يرجع إليه نادماً؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;